(7386662, 1159951, 62249, '<td valign="top">Good DOF. Wish there were a bit more light on the right side to see a hint more of the model''s face there.</td>', 'Good DOF. Wish there were a bit more light on the right side to see a hint more of the model''s face there.', '2015-07-14 00:19:14.000000', NULL, 1),
